	private record PatternInputs(Resource subject, IRI predicate, Value object, Resource[] contexts) {
		List<Value> values() {
			List<Value> values = new ArrayList<>();
			if (subject != null) {
				values.add(subject);
			}
			if (predicate != null) {
				values.add(predicate);
			}
			if (object != null) {
				values.add(object);
			}
			for (Resource context : contexts) {
				if (context != null) {
					values.add(context);
				}
			}
			return values;
		}
	}

